from pathlib import Path
import json,random,statistics,subprocess
root=Path.cwd();out=root/'target/validation-timing-20261004'
variants=[(name,'valid',mode) for name in ['empty','large','wrapper'] for mode in ['old','new']]
variants += [('empty',case,mode) for case in ['early_error','late_error'] for mode in ['old','new']]
raw={'/'.join(v):[] for v in variants}
env={'PATH':'/usr/bin:/bin','LANG':'en_US.UTF-8'}
def workers():
 lines=subprocess.check_output(['ps','-axo','pid,etime,%cpu,comm'],text=True).splitlines()
 return [line.strip() for line in lines if any(name in line for name in ['rustc','cargo','clippy-driver'])]
def sample(v):
 name,case,mode=v;iterations=1000 if case=='early_error' else 10
 result=subprocess.run([str(out/'timing'),str(out/f'{name}.borsh'),mode,case,str(iterations)],env=env,capture_output=True)
 assert result.returncode==0,(v,result.stderr)
 assert not result.stderr,result.stderr
 data=json.loads(result.stdout);data['first_ms']=data['first_ns']/1e6;data['warm_ms']=data['batch_ns']/data['iterations']/1e6
 assert data['valid']==(case=='valid')
 return data
for _ in range(3):
 for v in variants:sample(v)
rng=random.Random(2026100407);activity=[]
for iteration in range(100):
 activity.append({'round':iteration,'workers':workers()})
 rng.shuffle(variants)
 for v in variants:raw['/'.join(v)].append(sample(v))
 if (iteration+1)%20==0:print(iteration+1,'rounds',flush=True)
for name,case,_ in variants:
 a=raw['/'.join([name,case,'old'])];b=raw['/'.join([name,case,'new'])]
 assert all(x['error']==y['error'] for x,y in zip(a,b)),(name,case)
def stats(xs):
 ordered=sorted(xs);return {'median':statistics.median(ordered),'p95':ordered[94],'mean':statistics.mean(ordered),'min':ordered[0],'max':ordered[-1]}
summary={k:{field:stats([s[field] for s in samples]) for field in ['first_ms','warm_ms']} for k,samples in raw.items()}
(out/'results.json').write_text(json.dumps({'summary':summary,'raw':raw,'seed':2026100407,'runs':100,'warmups':3,'environment':env,'external_build_activity':activity},indent=2))
for k,v in summary.items():print(k,'first median',round(v['first_ms']['median'],6),'warm median',round(v['warm_ms']['median'],6),flush=True)
